  var ZH = { D: D, P: P, F: F, tier: tier, dur: dur, inT: function (n, u) { return dur(n, u) + "后"; }, expired: "已过期", title: { "dotBots Market": "dotBots 市场", "Testnet": "测试网" } };
  var UNIT_OF = { 15: "m", 16: "h", 17: "d" };
  function build(code, o) {
    var pack = { D: o.D, F: [], title: o.title, expired: o.expired, tier: function (t) { return t; } };
    pack.dur = function (n, u) { return o.dur.replace("$n", n).replace("$u", o.units[u]); };
    pack.inT = function (n, u) { return o.P[18].replace("{DUR}", pack.dur(n, u)); };
    pack.P = P.map(function (p, i) {
      var tpl = o.P[i];
      return [p[0], function (m) {
        if (i === 32 && !/\d/.test(m[1])) return null;
        if (i === 13 && !Object.prototype.hasOwnProperty.call(pack.D, m[1])) return null;
        var r = tpl;
        if (r.indexOf("{R1}") >= 0) r = r.split("{R1}").join(tr(m[1]) || m[1]);
        if (r.indexOf("{D1}") >= 0) r = r.split("{D1}").join(pack.D[m[1]]);
        if (r.indexOf("{TL1}") >= 0) r = r.split("{TL1}").join(m[1]);
        if (r.indexOf("{T2}") >= 0) r = r.split("{T2}").join(m[2]);
        if (r.indexOf("{DUR}") >= 0) r = r.split("{DUR}").join(i === 18 ? pack.dur(m[1], m[2]) : pack.dur(m[1], UNIT_OF[i]));
        return r.replace(/\$(\d)/g, function (_, k) { return m[+k] != null ? m[+k] : ""; });
      }];
    });
    pack.F = F.map(function (f, i) { return [f[0], o.F[i]]; });
    return pack;
  }
  for (var c in PACKS) PACKS[c] = build(c, PACKS[c]);
  PACKS.zh = ZH;
  var cur = null;

  function tr(s) {
    var K = cur; if (!K) return null;
    if (Object.prototype.hasOwnProperty.call(K.D, s)) return K.D[s];
    for (var i = 0; i < K.P.length; i++) {
      var m = s.match(K.P[i][0]);
      if (m) { var r = typeof K.P[i][1] === "function" ? K.P[i][1](m) : s.replace(K.P[i][0], K.P[i][1]); if (r != null) return r; }
    }
    var out = s, hit = false;
    for (var j = 0; j < K.F.length; j++) if (out.indexOf(K.F[j][0]) >= 0) { out = out.split(K.F[j][0]).join(K.F[j][1]); hit = true; }
    if (hit) out = out.replace(/\bin (\d+)([mhd])\b/g, function (_, n, u) { return K.inT(n, u); }).replace(/\bexpired\b/g, K.expired);
    return hit ? out : null;
  }
  function trFull(full) {
    var m = full.match(/^(\s*)([\s\S]*?)(\s*)$/);
    if (!m[2] || !/[A-Za-z]/.test(m[2])) return null;
    var t = tr(m[2]);
    return t == null ? null : m[1] + t + m[3];
  }

  var lang = "en", txt = new WeakMap(), att = new WeakMap(), ATTRS = ["placeholder", "title", "aria-label"];
  var SKIP = { SCRIPT: 1, STYLE: 1, TEXTAREA: 1, CODE: 1 };
  function skip(el) { return !el || SKIP[el.nodeName] || (el.closest && el.closest(".mono, [data-noi18n], svg")); }

  function doText(n) {
    var p = n.parentNode; if (skip(p)) return;
    var o = txt.get(n), en = o && n.data === o.tr ? o.en : n.data;
    if (lang !== "en") { var z = trFull(en); if (z != null) { if (z !== n.data) { txt.set(n, { en: en, tr: z }); n.data = z; } return; } }
    if (o && n.data === o.tr) { n.data = o.en; txt.delete(n); }
  }
  function doAttrs(el) {
    if (el.nodeType !== 1 || (el.closest && el.closest("[data-noi18n]"))) return;
    var store = att.get(el) || {};
    for (var i = 0; i < ATTRS.length; i++) {
      var a = ATTRS[i], v = el.getAttribute(a); if (v == null) continue;
      var o = store[a], en = o && v === o.tr ? o.en : v;
      if (lang !== "en") { var z = trFull(en); if (z != null) { if (z !== v) { store[a] = { en: en, tr: z }; el.setAttribute(a, z); } continue; } }
      if (o && v === o.tr) { el.setAttribute(a, o.en); delete store[a]; }
    }
    att.set(el, store);
  }
