    mn.innerHTML = ORDER.map(function (l) { return '<li><button type="button" role="menuitemradio" data-l="' + l + '" lang="' + HTMLLANG[l] + '"' + (l === "ur" ? ' dir="rtl"' : "") + ">" + NAMES[l] + "</button></li>"; }).join("");
    wrap.appendChild(mn);
